package com.ateliercampus.service;
import com.ateliercampus.dao.AtelierDao;import com.ateliercampus.model.Atelier;import java.sql.SQLException;import java.time.LocalDateTime;import java.util.List;
public class AtelierService {private final AtelierDao dao=new AtelierDao();public List<Atelier> list(String q)throws SQLException{return dao.list(q);}public Atelier find(long id)throws SQLException{return dao.find(id);}public int confirmed(long id)throws SQLException{return dao.countConfirmed(id);}public void save(Atelier a)throws Exception{if(a.getTitre()==null||a.getTitre().isBlank()||a.getTitre().length()>180)throw new IllegalArgumentException("Le titre est obligatoire (180 caractères maximum).");if(a.getDescription()==null||a.getDescription().isBlank())throw new IllegalArgumentException("La description est obligatoire.");if(a.getDateHeure()==null||!a.getDateHeure().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("La date doit être dans le futur.");if(a.getCapacite()<=0)throw new IllegalArgumentException("La capacité doit être strictement positive.");if(a.getId()!=null&&a.getCapacite()<dao.countConfirmed(a.getId()))throw new IllegalArgumentException("La capacité ne peut pas être inférieure aux inscriptions confirmées.");dao.save(a);}public void delete(long id)throws Exception{dao.delete(id);}}
